head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > focusMode]<br/>GridView 컴포넌트의 Body 또는 Footer 영역 선택 시 포커스 되는 형식을 설정합니다.",
    "validation" : [
        "focusFooter=true 인 경우 포커스 영역이 Footer 로 확장되며 Body 와 Footer 영역은 별도로 포커스 처리됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - con_focusMode : 미설정('') 이면 focusMode 속성을 부여하지 않음(기본값 cell 동작), cell/row/both/none 이면 해당 값 부여
//  - con_focusFooter : gdl_boolean(getText 로 true/false), 미설정('') 이면 속성 부여 안 함(기본값 false)
//  - selectedCellColor / selectedRowColor 를 서로 다른 색으로 지정하여 포커스 영역(Cell=파랑 / Row=연파랑)을 구분
//  - Footer 1행(ft1~ft4) 포함 그리드 → focusFooter=true 일때 Footer 영역이 Body 와 별도로 포커스됨을 확인
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // dataList 생성
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // 조건 값 수집
    let focusModeVal   = con_focusMode.getValue();          // '', cell, row, both, none
    let focusFooterVal = con_focusFooter.getText();         // '', true, false

    // Property 설정은 createCList 공통 함수 사용
    //  - focusMode 미설정이면 properties 에 포함하지 않아 기본값(cell) 동작
    //  - focusFooter 미설정이면 properties 에 포함하지 않아 기본값(false) 동작
    let properties = {
        dataList         : "data:dlt_bind",
        checkAllType     : "false",
        useShiftKey      : "true",
        useCtrlKey       : "true",
        dataDragSelect   : "true",
        selectedCellColor: "#1565c0",
        selectedRowColor : "#bbdefb"
    };
    if (focusModeVal !== '') {
        properties.focusMode = focusModeVal;
    }
    if (focusFooterVal !== '') {
        properties.focusFooter = focusFooterVal;
    }
    let cList = $c.gcm.createCList(properties);

    // 이벤트 바인딩은 createEList 공통 함수 사용
    //  - oncellclick : Body Cell 클릭 시 Body 포커스 상태 출력
    //  - onfooterclick : Footer Cell 클릭 시 Footer 포커스 상태 출력
    let eList = $c.gcm.createEList(["oncellclick", "onfooterclick"]);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    let lblFocusMode   = (focusModeVal === '')   ? '미설정(기본값 cell)'   : focusModeVal;
    let lblFocusFooter = (focusFooterVal === '') ? '미설정(기본값 false)' : focusFooterVal;
    $c.gcm.createLabel('label="focusMode=' + lblFocusMode + ' / focusFooter=' + lblFocusFooter + ' 로 GridView 생성 (Footer 1행 ft1~ft4, selectedCellColor=파랑·selectedRowColor=연파랑). Body Cell·Footer Cell 을 각각 클릭하여 Body/Footer 별도 포커스 확인"', '', 'label1');

    // target 생성 (Header 4컬럼 + gBody + Footer 1행)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' ' + eList + ' id="" style="width:520px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="focusMode 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="130" style="" inputType="text" id="column1" value="구분"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="column2" value="금액"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="column3" value="수량"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="column4" value="비고"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="130" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '<w2:footer style="" id="footer1">';
    strTarget += '<w2:row style="" id="row3">';
    strTarget += '<w2:column width="130" style="" inputType="text" id="ft1" value="합계"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="ft2" value="footer2"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="ft3" value="footer3"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="ft4" value="footer4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:footer>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// 현재 Body 포커스와 Footer 포커스 상태를 함께 출력하는 공통 함수
//  - Body 포커스 : getFocusedRowIndex / getFocusedColumnIndex (focusMode != 'none' 일때만 유지)
//  - Footer 포커스 : getFocusedFooterCell (focusFooter=true 이고 Footer Cell 클릭 시에만 반환)
//  - @spec6 : focusFooter=true 면 Body 와 Footer 가 별도로 포커스 처리되어 두 포커스가 동시에 유지됨
scwin.printFocusState = function (origin) {
    let bottom = wf_body_bottom.getObj("scwin");

    // Body 포커스 상태
    let bRow = target1.getFocusedRowIndex();
    let bCol = target1.getFocusedColumnIndex();
    bottom.setReturnValue("[Body 포커스] row=" + bRow + ", col=" + bCol);

    // Footer 포커스 상태 (focusFooter=true 일때만 값 반환)
    let footer = target1.getFocusedFooterCell();
    let result = '';
    if (footer && footer.length > 0) {
        for (let i = 0; i < footer.length; i++) {
            result += '{id:"' + footer[i].id + '", rowIndex:' + footer[i].rowIndex + ', colIndex:' + footer[i].colIndex + '}';
            if (i < footer.length - 1) {
                result += ', ';
            }
        }
        result = '[' + result + ']';
    } else {
        result = '[] (포커스된 Footer Cell 없음)';
    }
    bottom.setReturnValue("[Footer 포커스] focusFooter=" + target1.options.focusFooter + " / getFocusedFooterCell : " + result);
}



// oncellclick : 사용자가 Body Cell 을 클릭하면 발생
//  - Body 영역이 포커스되며, Footer 포커스(focusFooter=true 시)는 별도로 유지됨을 함께 출력
scwin.target1_oncellclick = function (rowIndex, columnIndex, columnId) {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();
    bottom.setReturnValue("=====Body Cell 클릭 (oncellclick) row=" + rowIndex + ",col=" + columnIndex + "=====");
    scwin.printFocusState("body");
}



// onfooterclick : 사용자가 Footer Cell 을 클릭하면 발생
//  - footerId : 클릭된 Footer Cell ID
//  - focusFooter=true 면 Footer 영역이 Body 와 별도로 포커스됨, false/미설정이면 Footer 포커스 안 됨
//  - Body 포커스는 그대로 유지됨을 함께 출력하여 'Body/Footer 별도 포커스' 확인
scwin.target1_onfooterclick = function (footerId) {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();
    bottom.setReturnValue("=====Footer Cell 클릭 (onfooterclick) footerId=" + footerId + "=====");
    scwin.printFocusState("footer");
}
